    "                          \"yfinance\", \"pandas\", \"numpy\", \"matplotlib\", \"--quiet\"])\n",
    "    print(\"✅ 库安装成功！\")\n",
    "except:\n",
    "    # 如果在Colab环境\n",
    "    try:\n",
    "        !pip install yfinance pandas numpy matplotlib --quiet\n",
    "        print(\"✅ 库安装成功！\")\n",
    "    except:\n",
    "        print(\"⚠️ 自动安装失败，请手动运行：pip install yfinance pandas numpy matplotlib\")"
